import axios from "axios";

const BASE_URL_LOCAL = "http://localhost:5005";
const BASE_URL_IP = "http://127.0.0.1:5005";

const API = axios.create({
  baseURL: process.env.REACT_APP_API_URL || BASE_URL_LOCAL,
  headers: {
    "Content-Type": "application/json"
  },
  timeout: 8000
});

// Interceptor to auto-fallback if localhost:5000 fails due to IPv4/IPv6 localhost binding
API.interceptors.response.use(
  (response) => response,
  async (error) => {
    const config = error.config;
    if (!config || config._retry) {
      return Promise.reject(error);
    }
    if (error.code === "ERR_NETWORK" || !error.response) {
      config._retry = true;
      config.baseURL = config.baseURL.includes("localhost") ? BASE_URL_IP : BASE_URL_LOCAL;
      console.warn(`Primary backend connection failed. Retrying with fallback: ${config.baseURL}`);
      return API(config);
    }
    return Promise.reject(error);
  }
);

export const analyzePayload = async (payload) => {
  const response = await API.post("/api/v1/analyze", payload);
  return response.data;
};

export const analyzeBarcode = async (ean) => {
  const response = await API.post("/api/v1/analyze", { ean });
  return response.data;
};

export const fetchProductInfo = async (barcode) => {
  const response = await API.get(`/api/v1/product/${barcode}`);
  return response.data;
};

export const fetchAuditQueue = async () => {
  const response = await API.get("/api/v1/audit/unmapped");
  return response.data;
};

export const checkHealth = async () => {
  const response = await API.get("/api/health");
  return response.data;
};

export default API;
